  render: () => (
    <Dialog title="Processing" open state="loading">
      <p>Please wait while we process your request...</p>
    </Dialog>
  ),
  play: async ({ canvas }) => {
    const dialog = canvas.getByRole('dialog');
    await expect(dialog).toBeVisible();
  },
};

