      <Button disabled={false}>Save</Button>
    </Card>
  ),
  play: async ({ canvas, userEvent }) => {
    await expect(canvas.getByRole('button', { name: /save/i })).toBeVisible();
    await userEvent.click(canvas.getByRole('button', { name: /save/i }));
  },
