  render: () => <Button kind="secondary" label="Secondary Button" />,
  play: async ({ canvas }) => {
    const button = canvas.getByRole('button', { name: /secondary button/i });
    await expect(button).toBeVisible();
    await expect(button).toBeEnabled();
  },
};

