  render: () => <Button kind="tertiary" label="Tertiary Button" />,
  play: async ({ canvas }) => {
    const button = canvas.getByRole('button', { name: /tertiary button/i });
    await expect(button).toBeVisible();
    await expect(button).toBeEnabled();
  },
};

