  render: () => <Button kind="primary" label="Disabled Button" disabled />,
  play: async ({ canvas }) => {
    const button = canvas.getByRole('button', { name: /disabled button/i });
    await expect(button).toBeVisible();
    await expect(button).toBeDisabled();
  },
};

